const llmOutput = $input.first().json.output?.[0]?.content?.[0]?.text || $input.first().json.message?.content || $input.first().json.text || '';
const webhookData = $('Webhook').first().json.body;

let queries;
try {
  // Strip markdown code blocks first
  const cleaned = llmOutput.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  const match = cleaned.match(/\[[\s\S]*\]/);
  queries = match ? JSON.parse(match[0]) : [];
} catch (e) {
  queries = llmOutput.split('\n').filter(q => q.trim().length > 5).slice(0, 5);
}

if (queries.length === 0) {
  queries = [webhookData.searchKeywords.join(' ')];
}

return [{
  json: {
    queries: queries.slice(0, 5),
    sessionId: webhookData.sessionId,
    companyName: webhookData.companyName,
    sectionPrompt: webhookData.sectionPrompt,
    searchKeywords: webhookData.searchKeywords,
    selectedDocIds: webhookData.selectedDocIds || [],
    maxChunks: webhookData.maxChunks || 20
  }
}];

const queries = $input.first().json.queries;
const OPENROUTER_KEY = '[REDACTED_SECRET]';

// OpenRouter uses the same OpenAI-compatible format
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/embeddings',
  headers: {
    'Authorization': `Bearer ${OPENROUTER_KEY}`,
    'Content-Type': 'application/json'
  },
  body: {
    model: 'openai/text-embedding-ada-002',
    input: queries
  },
  json: true
});

const embeddings = response.data.map(d => d.embedding);

return [{
  json: {
    ...$input.first().json,
    embeddings: embeddings
  }
}];

