const data = $input.first().json;
const k = 60;

const allResultSets = [...data.vectorResults, data.ftsResults];

const scoreMap = new Map();

for (const resultSet of allResultSets) {
  if (!Array.isArray(resultSet)) continue;
  resultSet.forEach((chunk, rank) => {
    const id = chunk.id;
    const rrfScore = 1 / (k + rank + 1);

    if (scoreMap.has(id)) {
      scoreMap.get(id).score += rrfScore;
    } else {
      scoreMap.set(id, {
        chunk: {
          id: chunk.id,
          content: chunk.content,
          file_name: chunk.file_name || null
        },
        score: rrfScore
      });
    }
  });
}

const candidates = Array.from(scoreMap.values())
  .sort((a, b) => b.score - a.score)
  .slice(0, 30);

return [{
  json: {
    sessionId: data.sessionId,
    companyName: data.companyName,
    sectionPrompt: data.sectionPrompt,
    maxChunks: data.maxChunks,
    candidates: candidates.map(c => c.chunk)
  }
}];

const data = $input.first().json;
const maxChunks = data.maxChunks || 20;
const candidates = data.candidates;
const llmOutput = data.rerankOutput || '';

let scores = [];
try {
  const match = llmOutput.match(/\[[\s\S]*\]/);
  scores = match ? JSON.parse(match[0]) : [];
} catch (e) {
  return [{
    json: {
      chunks: candidates.slice(0, maxChunks).map(c => ({
        id: c.id,
        content: c.content,
        file_name: c.file_name
      }))
    }
  }];
}

const scoreMap = new Map();
for (const s of scores) {
  scoreMap.set(Number(s.id), s.score);
}

const rankedChunks = candidates
  .map(c => ({
    ...c,
    relevanceScore: scoreMap.get(c.id) ?? 5
  }))
  .filter(c => c.relevanceScore >= 6)
  .sort((a, b) => b.relevanceScore - a.relevanceScore)
  .slice(0, maxChunks)
  .map(({ relevanceScore, ...chunk }) => chunk);

const finalChunks = rankedChunks.length >= 3
  ? rankedChunks
  : candidates.slice(0, maxChunks);

// Return only essential fields — no extra data
return [{
  json: {
    chunks: finalChunks.map(c => ({
      id: c.id,
      content: c.content,
      file_name: c.file_name || null
    }))
  }
}];

