const fullText = $input.first().json.text || $input.first().json.data || '';

// Define the sections we want to keep
const RELEVANT_SECTIONS = [
  // Section markers commonly found in Indian annual reports
  { start: /consolidated\s+(financial\s+)?statement/i, end: /standalone\s+(financial\s+)?statement|notes\s+to\s+.*financial/i, label: 'consolidated_financials' },
  { start: /standalone\s+(financial\s+)?statement/i, end: /notes\s+to\s+.*financial|cash\s+flow/i, label: 'standalone_financials' },
  { start: /balance\s+sheet|statement\s+of\s+financial\s+position/i, end: /statement\s+of\s+profit|income\s+statement/i, label: 'balance_sheet' },
  { start: /cash\s+flow\s+statement|statement\s+of\s+cash\s+flow/i, end: /notes\s+to|significant\s+accounting/i, label: 'cash_flow' },
  { start: /management\s+discussion|management('s)?\s+discussion\s+(&|and)\s+analysis|md\s*&\s*a/i, end: /director('s)?\s+report|corporate\s+governance/i, label: 'mda' },
  { start: /director('s)?\s+report|board('s)?\s+report/i, end: /corporate\s+governance|auditor/i, label: 'directors_report' },
  { start: /related\s+party\s+transaction/i, end: /additional\s+information|other\s+notes/i, label: 'related_party' },
  { start: /auditor('s)?\s+report|independent\s+auditor/i, end: /annexure|financial\s+statement/i, label: 'auditor_report' },
  { start: /statement\s+of\s+profit\s+(and|&)\s+loss|income\s+statement/i, end: /balance\s+sheet|cash\s+flow|notes/i, label: 'profit_loss' }
];

// Split into pages/sections (using form feeds or page markers)
const pages = fullText.split(/\f|\n{4,}|(?=\n.*page\s+\d+)/i);

const relevantContent = [];
let currentSection = null;
let capturing = false;

for (const page of pages) {
  const pageText = page.trim();
  if (pageText.length < 50) continue;

  // Check if this page starts a relevant section
  for (const section of RELEVANT_SECTIONS) {
    if (section.start.test(pageText)) {
      currentSection = section.label;
      capturing = true;
      break;
    }
    if (capturing && section.end && section.end.test(pageText)) {
      // We've hit the end marker of current section
      relevantContent.push({
        text: pageText,
        section: currentSection
      });
      capturing = false;
      currentSection = null;
      break;
    }
  }

  if (capturing) {
    relevantContent.push({
      text: pageText,
      section: currentSection
    });
  }
}

// If regex-based extraction found very little, fall back to keyword density filtering
if (relevantContent.length < 5) {
  const HIGH_VALUE_KEYWORDS = [
    'revenue', 'ebitda', 'profit', 'loss', 'margin', 'growth',
    'cash flow', 'balance sheet', 'debt', 'equity', 'roe', 'roce',
    'management discussion', 'director', 'auditor', 'related party',
    'operating', 'capex', 'working capital', 'dividend',
    'consolidated', 'standalone', 'segment', 'subsidiary'
  ];

  for (const page of pages) {
    const lower = page.toLowerCase();
    const keywordHits = HIGH_VALUE_KEYWORDS.filter(kw => lower.includes(kw)).length;
    // Keep pages with 3+ financial keyword matches
    if (keywordHits >= 3 && page.trim().length > 100) {
      relevantContent.push({
        text: page.trim(),
        section: 'keyword_matched'
      });
    }
  }
}

// Reconstruct as single text with section markers
const filteredText = relevantContent
  .map(r => `[SECTION: ${r.section}]\n${r.text}`)
  .join('\n\n---\n\n');

return [{
  json: {
    ...($input.first().json),
    text: filteredText,
    original_pages: pages.length,
    filtered_sections: relevantContent.length,
    is_filtered: true
  }
}];

